// The bundled, curated RWA list (generated by scripts/buildRwaAssets.js from official sources).
// Entries that fail validation here are dropped at load time (never shown).
import RAW from "./rwaAssets.json";
import { REGION_RULES } from "../config";

const ISSUERS = ["ondo", "xstocks", "paxos", "tether", "ondo-stellar", "etherfuse"];
const CATEGORIES = ["stock", "etf", "gold", "treasury"];
const EVM_CHAINS = { ETH: 1, BSC: 56 };

export const CATEGORY_LABELS = { all: "All", stock: "Stocks", etf: "ETFs", gold: "Gold", treasury: "Treasuries" };

// Returns null if valid, else the reason.
export const assetProblem = (a) => {
  if (!a || typeof a !== "object") return "not an object";
  if (!a.id || !a.symbol || !a.name) return "missing id/symbol/name";
  if (!ISSUERS.includes(a.issuer)) return `bad issuer ${a.issuer}`;
  if (!CATEGORIES.includes(a.category)) return `bad category ${a.category}`;
  if (!REGION_RULES[a.regions]) return `no region rule ${a.regions}`;
  if (!Number.isInteger(a.decimals) || a.decimals < 0 || a.decimals > 36) return "bad decimals";
  if (a.chain === "XLM") {
    if (!/^[A-Za-z0-9]{1,12}$/.test(a.code || "")) return "bad stellar code";
    if (!/^G[A-Z2-7]{55}$/.test(a.stellarIssuer || "")) return "bad stellar issuer";
    return null;
  }
  if (!EVM_CHAINS[a.chain]) return `bad chain ${a.chain}`;
  if (a.chainId !== EVM_CHAINS[a.chain]) return "chainId mismatch";
  if (!/^0x[0-9a-fA-F]{40}$/.test(a.address || "")) return "bad address";
  if (a.logo && !/^https:\/\//.test(a.logo)) return "logo not https";
  return null;
};

export const validateAssets = (list) => {
  const seen = new Set();
  const ok = [];
  const dropped = [];
  (list || []).forEach((a) => {
    const why = assetProblem(a) || (seen.has(a.id) ? "duplicate id" : null);
    if (why) dropped.push({ id: a && a.id, why });
    else {
      seen.add(a.id);
      ok.push(a);
    }
  });
  return { ok, dropped };
};

// Expand the compact bundled format (see scripts/buildRwaAssets.js `compact`) to full entries:
// { id, symbol, name, underlying, issuer, category, chain, chainId, address, code, stellarIssuer,
//   decimals, logo, multiplier: { kind, oracle }, marketHours, termsUrl, regions }.
export const expandAssets = (raw) => {
  if (Array.isArray(raw)) return raw; // already expanded (tests / old format)
  if (!raw || !Array.isArray(raw.rows) || !raw.issuers) return [];
  const out = [];
  raw.rows.forEach((r) => {
    const [symbol, name, underlying, issuer, category, chains, addrs, decimals, logo] = r;
    const iss = raw.issuers[issuer] || {};
    const chainList = String(chains || "").split("|");
    const addrList = String(addrs || "").split("|");
    let logoUrl = null;
    if (typeof logo === "string") {
      const i = logo.indexOf(":");
      const pre = raw.logoPrefixes && raw.logoPrefixes[Number(logo.slice(0, i))];
      if (pre) logoUrl = pre + logo.slice(i + 1);
    }
    chainList.forEach((chain, k) => {
      const addr = addrList.length === chainList.length ? addrList[k] : addrList[0];
      const stellar = chain === "XLM";
      const [code, stellarIssuer] = stellar ? addr.split(":") : [null, null];
      out.push({
        id: `${symbol}-${chain}`,
        symbol,
        name,
        underlying,
        issuer,
        category,
        chain,
        chainId: EVM_CHAINS[chain] || null,
        address: stellar ? null : addr,
        code: stellar ? code : null,
        stellarIssuer: stellar ? stellarIssuer : null,
        decimals,
        logo: logoUrl,
        multiplier: { kind: iss.multiplier || "none", oracle: (iss.oracle && iss.oracle[chain]) || null },
        marketHours: iss.marketHours,
        termsUrl: iss.termsUrl,
        regions: iss.regions,
      });
    });
  });
  return out;
};

const { ok: ASSETS } = validateAssets(expandAssets(RAW));
export const RWA_ASSETS = ASSETS;

export const assetById = (id) => RWA_ASSETS.find((a) => a.id === id) || null;

// Search + category filter (case-insensitive on symbol, name, underlying).
export const filterAssets = (list, { category = "all", query = "" } = {}) => {
  const q = query.trim().toLowerCase();
  return list.filter((a) => {
    if (category !== "all" && a.category !== category) return false;
    if (!q) return true;
    return (
      a.symbol.toLowerCase().includes(q) ||
      a.name.toLowerCase().includes(q) ||
      String(a.underlying || "").toLowerCase().includes(q)
    );
  });
};

// Stellar assets have no contract address on DefiLlama: use their CoinGecko ids (checked 2026-11-18).
const STELLAR_LLAMA = { USDY: "coingecko:ondo-us-dollar-yield", CETES: "coingecko:cetes" };

// Key used for DefiLlama ("ethereum:0x…", "bsc:0x…", "coingecko:…"); null if unknown.
export const llamaKey = (a) => {
  if (!a) return null;
  if (a.chain === "ETH") return `ethereum:${a.address.toLowerCase()}`;
  if (a.chain === "BSC") return `bsc:${a.address.toLowerCase()}`;
  if (a.chain === "XLM") return STELLAR_LLAMA[a.code] || null;
  return null;
};
